399	    /**
400	     * The owner's fiscal year, derived at response time from the business-day-adjusted
401	     * {@link #registrationDate} (stamped business-day-adjusted at creation) as {@code FY<YY>},
402	     * where the fiscal year starts on 1 July and {@code YY} is the last two digits of the fiscal
403	     * year (the calendar year in which it ends). {@code null} when the registration date is absent.
404	     * Not persisted.
405	     */
406	    public String getFiscalYear() {
