505	    /**
506	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
507	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
508	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
509	     * digit from the right, subtracting 9 from any result over 9, and taking
510	     * {@code (10 - sum % 10) % 10}. Not persisted.
511	     */
512	    public Integer getCheckDigit() {
513	        if (this.customerCode == null) {
514	            return null;
515	        }
516	        int sum = 0;
517	        boolean dbl = true;
518	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
519	            char c = this.customerCode.charAt(i);
520	            if (c < '0' || c > '9') {
521	                continue;
522	            }
523	            int d = c - '0';
524	            if (dbl) {
525	                d *= 2;
526	                if (d > 9) {
527	                    d -= 9;
528	                }
529	            }
530	            sum += d;
531	            dbl = !dbl;
532	        }
533	        return (10 - (sum % 10)) % 10;
534	    }
