536	    /**
537	     * A display-only derived string composing the owner's canonical contact and household values:
538	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
539	     * canonical E.164 form and the email lower-cased; an absent email or householdId contributes an
540	     * empty segment. Derived at response time and exposed as a read-only response field only — it
541	     * drives no check. Duplicate detection is purely household-based (see
542	     * {@code CheckOwnerHouseholdUnique}, which compares {@link #getHouseholdId() householdId}); this
543	     * key is not consulted. Not persisted.
544	     */
545	    public String getIdentityKey() {
546	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
547	    }
