553	    /**
554	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
555	     * national digits (everything after the country code) grouped in threes and space-separated —
556	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
557	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
558	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
559	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
560	     */
561	    public String getTelephoneDisplay() {
562	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
563	            return null;
564	        }
565	        String digits = this.telephone.substring(1);
566	        int countryCodeLength;
567	        if (digits.startsWith("61")) {
568	            countryCodeLength = 2;
569	        }
570	        else if (digits.startsWith("1")) {
571	            countryCodeLength = 1;
572	        }
573	        else {
574	            countryCodeLength = 2;
575	        }
576	        String countryCode = digits.substring(0, countryCodeLength);
577	        String national = digits.substring(countryCodeLength);
578	        StringBuilder display = new StringBuilder("+").append(countryCode);
579	        for (int i = 0; i < national.length(); i += 3) {
580	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
581	        }
582	        return display.toString();
583	    }
